WITH parsed AS (SELECT id, host, log_ts, latency_ms, status_code, payload_json, SIZE(context) AS num_context, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text FROM app_logs) SELECT CASE WHEN status_code >= 410 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_code_tier, AVG(num_context) AS avg_num_context, CORR(status_code, latency_ms) AS corr_status_code_latency_ms, COUNT_IF(host = 'h3') AS h3_events, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS duration_min, PERCENTILE_APPROX(status_code, 0.9) AS status_code_p90 FROM parsed GROUP BY CUBE (CASE WHEN status_code >= 410 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY avg_num_context DESC
